const anio = new Date().getFullYear() + 1;

return [{
  json: {
    anio,
    pais: 'CO'
  }
}];

const input = $input.all();
const anioEsperado = $('Preparar año siguiente').first().json.anio;
const festivos = [];

for (const item of input) {
  const data = item.json;
  if (Array.isArray(data)) {
    festivos.push(...data);
  } else if (Array.isArray(data.body)) {
    festivos.push(...data.body);
  } else if (data && data.date) {
    festivos.push(data);
  }
}

if (festivos.length === 0) {
  throw new Error('Nager.Date no devolvió festivos. Se cancela la sincronización.');
}

const fechas = new Set();
const resultado = [];

for (const festivo of festivos) {
  const fecha = festivo.date;
  const nombre = festivo.localName || festivo.name;

  if (typeof fecha !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(fecha) || !nombre) {
    throw new Error('La API devolvió un festivo con fecha o nombre inválido.');
  }

  const anio = Number(fecha.slice(0, 4));
  if (anio !== anioEsperado) {
    throw new Error(`Se recibió una fecha fuera del año solicitado: ${fecha}`);
  }
  if (fechas.has(fecha)) {
    throw new Error(`La API devolvió una fecha duplicada: ${fecha}`);
  }
  if (nombre.length > 100) {
    throw new Error(`El nombre del festivo supera 100 caracteres: ${fecha}`);
  }

  fechas.add(fecha);
  resultado.push({ json: { fecha, nombre, anio } });
}

return resultado;
